def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    rem = 100 - n
    if rem <= 0:
        return 'D'
    last_me, last_opp = history[-1]
    if n <= 5:
        return 'C'

    oc = 0
    for m, o in history:
        if o == 'C':
            oc += 1
    od = n - oc

    d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        d_streak += 1
        i -= 1

    c_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        c_streak += 1
        i -= 1

    rl = 10 if n >= 10 else n
    rs = n - rl
    rec_oc = 0
    for i in range(rs, n):
        if history[i][1] == 'C':
            rec_oc += 1

    my_c_prev = 0
    my_d_prev = 0
    c_after_c = 0
    c_after_d = 0
    d_after_c = 0
    d_after_d = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        co = history[i][1]
        if pm == 'C':
            my_c_prev += 1
            if co == 'C':
                c_after_c += 1
            else:
                d_after_c += 1
        else:
            my_d_prev += 1
            if co == 'C':
                c_after_d += 1
            else:
                d_after_d += 1

    rate_c = c_after_c / my_c_prev if my_c_prev else 0.5
    rate_d = c_after_d / my_d_prev if my_d_prev else 0.5

    def_host = False
    if n >= 6 and oc <= max(1, n // 7) and od > (n * 2) // 3:
        def_host = True
    if n >= 8 and rec_oc == 0 and d_streak >= 8:
        def_host = True
    if n >= 8 and od > (n * 7) // 10 and rec_oc <= 2:
        def_host = True
    if n >= 10 and od > (n * 4) // 5 and oc <= 1:
        def_host = True

    if rem <= 1:
        return 'D'
    if def_host:
        return 'D'

    forgiving_evidence = my_d_prev >= 1 and c_after_d > d_after_d and rate_d > 0.5 and oc > n * 0.4
    avg_rate = (rate_c + rate_d) * 0.5
    independent_like = my_d_prev >= 3 and abs(rate_c - rate_d) <= 0.18 and avg_rate > 0.55
    exploitable = oc > n * 0.4 and (forgiving_evidence or independent_like)

    if last_opp == 'D':
        if independent_like and not forgiving_evidence:
            return 'D'
        if d_streak >= 12:
            return 'C' if rec_oc >= 2 and oc > n * 0.3 else 'D'
        if d_streak >= 10 and rec_oc >= 1 and rng.random() < 0.08:
            return 'C'
        if oc > n * 0.45 and d_streak <= 10:
            return 'C'
        if rec_oc >= 3 and d_streak <= 6:
            return 'C'
        if d_streak == 1 and last_me == 'C' and oc > n * 0.6:
            return 'C'
        if d_after_c >= max(2, n // 3) and rec_oc <= 4:
            return 'D'
        return 'D'

    if last_me == 'D' and not exploitable:
        return 'C'
    if exploitable:
        return 'D'

    if d_after_c >= 2 and c_streak >= 1 and n > 25 and (my_d_prev < 2 or rate_d > 0.35) and rng.random() < 0.18:
        return 'D'

    if rem <= 2:
        if rec_oc >= 4 or oc > n * 0.7:
            return 'D'

    if rem <= 5 and oc > n * 0.7 and (forgiving_evidence or rng.random() < 0.05):
        return 'D'

    return 'C'
